#!/usr/bin/env bash
# Block agent modification of forge's generated Vibe guard config.
#
# .vibe/hooks.toml, .vibe/forge-roster.json, .vibe/agents/ and .vibe/prompts/
# are generated by install-forge-vibe / forge-gen-vibe-hooks. They ARE the
# safety layer: an agent that can edit hooks.toml can strip `strict`, delete
# guards, or rewrite the roster, and gitignored means git never restores
# them. Regeneration is a CLI job (install-forge-vibe), never an agent edit.
#
# Fires on:
#   - Edit / Write tools whose file_path lands under a protected .vibe path
#   - Bash commands that delete, move, or overwrite a protected .vibe path
#     (rm/mv/cp/truncate/redirect). The generator CLIs write via Python
#     file APIs, not shell redirection, so they are unaffected.
set -e
INPUT=$(cat)

# Protected path prefixes (repo-relative). Keep in sync with install_vibe.py.
PROTECTED_RE='(^|/)\.vibe/(hooks\.toml|forge-roster\.json|agents/|prompts/)'

# --- Edit / Write branch -------------------------------------------------
FILE_PATH=$(echo "$INPUT" | jq -r '.tool_input.file_path // empty')
if [ -n "$FILE_PATH" ]; then
    if echo "$FILE_PATH" | grep -qE "$PROTECTED_RE"; then
        echo "BLOCKED: $FILE_PATH is forge-generated Vibe guard config. Regenerate with 'install-forge-vibe' (or 'forge-gen-vibe-hooks'); do not edit or delete it by hand or by agent." >&2
        exit 2
    fi
    exit 0
fi

# --- Bash branch ---------------------------------------------------------
COMMAND=$(echo "$INPUT" | jq -r '.tool_input.command // empty')
[ -z "$COMMAND" ] && exit 0

# Match destructive shell verbs aimed at a protected .vibe path.
# Covers: rm -f .vibe/hooks.toml, mv .vibe/agents/x.toml /tmp, cp over it,
# truncate, and redirects (> .vibe/hooks.toml, >> ..., tee).
if echo "$COMMAND" | grep -qE "(^|[;&|]\s*)(rm|mv|cp|truncate|tee)\b.*$PROTECTED_RE|$PROTECTED_RE.*(>|>>)\s|\b(>|>>)\s*[^;&|]*$PROTECTED_RE"; then
    echo "BLOCKED: shell command modifies forge-generated Vibe guard config under .vibe/. Regenerate with 'install-forge-vibe'; agents must not delete or overwrite these files." >&2
    exit 2
fi
exit 0
